import{_ as o,a0 as i,w as l,s as d,I as n,x as e,a1 as p,A as s,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在Debian上設置USB網絡打印機和掃描儀服務器 | LCTT x X-CMD","titleTemplate":false,"description":"在Debian上設置USB網絡打印機和掃描儀服務器 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Debian上設置USB網絡打印機和掃描儀服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Debian上設置USB網絡打印機和掃描儀服務器 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140812 How to set up a USB network printer and scanner server on Debian","title":"在Debian上設置USB網絡打印機和掃描儀服務器","tag":"201411","desc":""},"relativePath":"201411/20140812 How to set up a USB network printer and scanner server on Debian.md","filePath":"[post].md"}'),f={name:"201411/20140812 How to set up a USB network printer and scanner server on Debian.md"};function m(u,t,g,b,S,c){const r=i("Link");return l(),d("div",null,[t[29]||(t[29]=n("h1",{id:"在debian上設置usb網絡打印機和掃描儀服務器",tabindex:"-1"},[e("在Debian上設置USB網絡打印機和掃描儀服務器 "),n("a",{class:"header-anchor",href:"#在debian上設置usb網絡打印機和掃描儀服務器","aria-label":"Permalink to “在Debian上設置USB網絡打印機和掃描儀服務器”"},"​")],-1)),t[30]||(t[30]=n("p",null,"假定你想要在你的家庭/辦公網絡中設置一台Linux打印服務器，而你手頭上卻只有USB打印機可用（因為他們比那些有着內建網絡接口或無線模組的打印機要便宜得多）。此外，如果這些設備中有一台是一體化的，而你也想要通過網絡共享其整合的掃描儀，這該怎麼辦？在本文中，我將介紹怎樣安裝並共享一台USB一體機（Epson CX3900噴墨打印機和掃描儀），一台USB激光打印機（Samsung ML-1640），以及作為錦上添花，配置一台PDF打印機。所有這一切，我們都將在GNU/Linux Debian 7.2 [Wheezy]服務器中實現。",-1)),t[31]||(t[31]=n("p",null,"儘管這些打印機看起來有點老舊了（我是在2007年買的Epson一體機，2009年買的激光打印機），但我仍然相信我從安裝過程中學到的東西也一樣能應用到該品牌的新產品和其它品牌中去：有一些預編譯的.deb包驅動可用，而其它驅動可以從倉庫中直接安裝。畢竟，它是重要的基本原則。",-1)),t[32]||(t[32]=n("h3",{id:"先決條件",tabindex:"-1"},[e("先決條件 "),n("a",{class:"header-anchor",href:"#先決條件","aria-label":"Permalink to “先決條件”"},"​")],-1)),n("p",null,[t[1]||(t[1]=e("要設置網絡打印機和掃描儀，我們將使用",-1)),p(r,{href:"https://www.cups.org/"},{default:s(()=>[...t[0]||(t[0]=[e("CUPS",-1)])]),_:1}),t[2]||(t[2]=e("，它是一個用於Linux/UNIX/OSX的開源打印系統。",-1))]),t[33]||(t[33]=a(`<pre><code># aptitude install cups cups-pdf 
</code></pre><p><strong>排障提示</strong>：根據你的系統狀況（這個問題很可能在手動安裝包失敗後，或者缺少依賴包的時候會發生），在安裝cups和cups-pdf前端包管理系統可能會提示你卸載許多包以嘗試解決當前依賴問題。如果這種情況真的發生，你只有兩個選擇：</p><p>1）通過另外一個前端包管理系統安裝包，如apt-get。注意，並不建議進行這樣的處理，因為它不會解決當前的問題。</p><p>2）運行以下命令：aptitude update &amp;&amp; aptitude upgrade。該命令會修復此問題，並同時更新包到最新版本。</p><h3 id="配置cups" tabindex="-1">配置CUPS <a class="header-anchor" href="#配置cups" aria-label="Permalink to “配置CUPS”">​</a></h3><p>為了能夠訪問CUPS的網頁接口，我們需要至少對cupsd.conf文件（用於CUPS的服務器配置文件）進行一次最低限度的修改。在進行修改前，讓我們為cupsd.conf做個備份副本：</p><pre><code># cp cupsd.conf cupsd.conf.bkp 
</code></pre><p>然後，編輯原始文件（下面只顯示了最為有關聯的部分）：</p><ul><li><strong>Listen</strong>：監聽指定的地址和端口，或者域套接口路徑。</li><li><strong>Location /path</strong>：為該名字所代表的位置指定訪問控制。</li><li><strong>Order</strong>：指定HTTP訪問控制順序（allow,deny或deny,allow）。Order allow,deny是説允許規則先於（並且優先處理）拒絕規則。</li><li><strong>DefaultAuthType</strong> (也可以用<strong>AuthType</strong>)： 指定默認使用的認證類型。Basic是指使用/etc/passwd文件來認證CUPS中的用户。</li><li><strong>DefaultEncryption</strong>：指定認證請求所使用的加密類型。</li><li><strong>WebInterface</strong>：指定是否啓用網頁接口。</li></ul><hr><pre><code>	# Listen for connections from the local machine
	Listen 192.168.0.15:631

	# Restrict access to the server
	&lt;Location /&gt;
  	  Order allow,deny
  	  Allow 192.168.0.0/24
	&lt;/Location&gt;

	# Default authentication type, when authentication is required
	DefaultAuthType Basic
 	DefaultEncryption IfRequested

	# Web interface setting
	WebInterface Yes

	# Restrict access to the admin pages
	&lt;Location /admin&gt;
  	  Order allow,deny
  	  Allow 192.168.0.0/24
	&lt;/Location&gt;
</code></pre><p>現在，讓我們重啓CUPS來應用修改：</p><pre><code># service cups restart 
</code></pre><p>為了允許另外一個用户（除了root之外）修改打印機設置，我們必須像下面這樣添加他/她到lp（授權對打印機硬件的訪問並啓用用户管理打印任務）和lpadmin（擁有打印優先）組。如果在你當前網絡設置沒有必要或不需要該設置，你可以不用理會該步驟。</p><pre><code># adduser xmodulo lp
# adduser xmodulo lpadmin 
</code></pre><p><img src="https://farm4.staticflickr.com/3873/14705919960_9a25101098_o.png" alt=""></p><h3 id="通過網頁接口配置網絡打印機" tabindex="-1">通過網頁接口配置網絡打印機 <a class="header-anchor" href="#通過網頁接口配置網絡打印機" aria-label="Permalink to “通過網頁接口配置網絡打印機”">​</a></h3>`,17)),n("p",null,[t[4]||(t[4]=e("1、 啓動網頁瀏覽器，並打開CUPS接口 ",-1)),t[5]||(t[5]=n("code",null,"http://<Server IP>:Port",-1)),t[6]||(t[6]=e("，這裏在我們的例子中是",-1)),p(r,{href:"http://192.168.0.15:631"},{default:s(()=>[...t[3]||(t[3]=[e("http://192.168.0.15:631",-1)])]),_:1}),t[7]||(t[7]=e("：",-1))]),t[34]||(t[34]=a('<p><img src="https://farm4.staticflickr.com/3878/14889544591_284015bcb5_z.jpg" alt=""></p><p>2、 轉到<strong>管理</strong>標籤，然後點擊<em>添加打印機</em>：</p><p><img src="https://farm4.staticflickr.com/3910/14705919940_fe0a08a8f7_o.png" alt=""></p><p>3、 選擇你的打印機；在本例中，<strong>EPSON Stylus CX3900 @ debian (Inkjet Inkjet Printer)</strong>，然後點擊<strong>繼續</strong>：</p><p><img src="https://farm6.staticflickr.com/5567/14706059067_233fcf9791_z.jpg" alt=""></p><p>4、 是時候為打印機取個名字，並指定我們是否想要從當前工作站共享它：</p><p><img src="https://farm6.staticflickr.com/5570/14705957499_67ea16d941_z.jpg" alt=""></p><p>5、 安裝驅動——選擇品牌並點擊<strong>繼續</strong>。</p><p><img src="https://farm6.staticflickr.com/5579/14889544531_77f9f1258c_o.png" alt=""></p>',9)),n("p",null,[t[9]||(t[9]=e("6、 如果打印機如果不被CUPS支持（沒有在下一頁中列出來），我們必須從生產廠家的網站上下載驅動（如",-1)),p(r,{href:"http://download.ebz.epson.net/dsc/search/01/search/?OSC=LX"},{default:s(()=>[...t[8]||(t[8]=[e("http://download.ebz.epson.net/dsc/search/01/search/?OSC=LX",-1)])]),_:1}),t[10]||(t[10]=e("），安裝完後回到該頁。",-1))]),t[35]||(t[35]=a(`<p><img src="https://farm4.staticflickr.com/3896/14706058997_e2a2214338_z.jpg" alt=""></p><p><img src="https://farm4.staticflickr.com/3874/14706000928_c9dc74c80e_z.jpg" alt=""></p><p><img src="https://farm4.staticflickr.com/3837/14706058977_e494433068_o.png" alt=""></p><p>7、 注意，預編譯的.deb文件必須從我們使用的機器上發送（例如，通過sftp或scp）到打印服務器（當然，如果我們有一個直接的下載鏈接就更加簡單了，而不用下載按鈕了）：</p><p><img src="https://farm6.staticflickr.com/5581/14706000878_f202497d0a_z.jpg" alt=""></p><p>8、 在將.deb文件放到服務器上後，我們就可以安裝了：</p><pre><code> # dpkg -i epson-inkjet-printer-escpr_1.4.1-1lsb3.2_i386.deb 
</code></pre><p><strong>排障提示</strong>：如果lsb包（一個第三方Linux應用編寫者可以依賴標準核心系統）沒有安裝，那麼驅動會無法安裝：</p><p><img src="https://farm4.staticflickr.com/3840/14705919770_87e5803f95_z.jpg" alt=""></p><p>我們將安裝lsb，然後嘗試再次安裝打印機驅動：</p><pre><code># aptitude install lsb
# dpkg -i epson-inkjet-printer-escpr_1.4.1-1lsb3.2_i386.deb
</code></pre><p>9、 現在，我們可以返回到第五步並安裝打印機：</p><p><img src="https://farm6.staticflickr.com/5569/14705957349_3acdc26f91_z.jpg" alt=""></p><h3 id="配置網絡掃描儀" tabindex="-1">配置網絡掃描儀 <a class="header-anchor" href="#配置網絡掃描儀" aria-label="Permalink to “配置網絡掃描儀”">​</a></h3>`,14)),n("p",null,[t[13]||(t[13]=e("現在，我們將繼續配置打印機服務器來共享掃描儀。首先，安裝",-1)),p(r,{href:"http://www.xsane.org/"},{default:s(()=>[...t[11]||(t[11]=[e("xsane",-1)])]),_:1}),t[14]||(t[14]=e("，這是",-1)),p(r,{href:"http://www.sane-project.org/"},{default:s(()=>[...t[12]||(t[12]=[e("SANE",-1)])]),_:1}),t[15]||(t[15]=e("——掃描儀快捷訪問的前端：",-1))]),t[36]||(t[36]=a(`<pre><code># aptitude install xsane 
</code></pre><p>接下來，讓我們編輯/etc/default/saned文件以啓用saned服務：</p><pre><code># Set to yes to start saned                                                     
RUN=yes
</code></pre><p>最後，我們將檢查saned是否已經在運行了（很可能不在運行哦——那麼我們將啓動服務並再來檢查）：</p><pre><code># ps -ef | grep saned | grep -v grep
# service saned start 
</code></pre><h3 id="配置另一台網絡打印機" tabindex="-1">配置另一台網絡打印機 <a class="header-anchor" href="#配置另一台網絡打印機" aria-label="Permalink to “配置另一台網絡打印機”">​</a></h3><p>通過CUPS，你可以配置多台網絡打印機。讓我們通過CUPS配置一台額外的打印機：Samsung ML-1640，它是一台USB打印機。</p><p>splix包包含了單色（ML-15xx, ML-16xx, ML-17xx, ML-2xxx）和彩色（CLP-5xx, CLP-6xx）Samsung打印機驅動。此外，此包的詳細信息中指出，一些新命名的Samsung打印機，如Xerox Phaser 6100也適用此驅動。</p><pre><code># aptitude install splix 
</code></pre><p>然後我們將使用CUPS網頁接口來安裝打印機，就像前面一樣：</p><p><img src="https://farm4.staticflickr.com/3872/14705957329_4f38a94867_o.png" alt=""></p><h3 id="安裝pdf打印機" tabindex="-1">安裝PDF打印機 <a class="header-anchor" href="#安裝pdf打印機" aria-label="Permalink to “安裝PDF打印機”">​</a></h3><p>接下來，讓我們在打印服務器上配置一台PDF打印機。這樣，你就可以將來自客户計算機的文檔轉換成PDF格式了。</p><p>由於我們已經安裝了cups-pdf包，PDF打印機就已經自動安裝好了，可以通過網頁接口驗證：</p><p><img src="https://farm6.staticflickr.com/5558/14705919650_bc1a1e0b43_z.jpg" alt=""></p><p>當選定PDF打印機後，文檔將被寫入可配置目錄（默認是~/PDF），或者也可以通過後續處理命令進行復制。</p><p>在下一篇文章中，我們將配置桌面客户端來通過網絡訪問打印機和掃描儀。</p><hr>`,18)),n("p",null,[t[17]||(t[17]=e("via: ",-1)),p(r,{href:"http://xmodulo.com/2014/08/usb-network-printer-and-scanner-server-debian.html"},{default:s(()=>[...t[16]||(t[16]=[e("http://xmodulo.com/2014/08/usb-network-printer-and-scanner-server-debian.html",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=e("作者：",-1)),p(r,{href:"http://www.gabrielcanepa.com.ar/"},{default:s(()=>[...t[18]||(t[18]=[e("Gabriel Cánepa",-1)])]),_:1}),t[22]||(t[22]=e(" 譯者：",-1)),p(r,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[19]||(t[19]=[e("GOLinux",-1)])]),_:1}),t[23]||(t[23]=e(" 校對：",-1)),p(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[20]||(t[20]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[26]||(t[26]=e("本文由 ",-1)),p(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[24]||(t[24]=[e("LCTT",-1)])]),_:1}),t[27]||(t[27]=e(" 原創翻譯，",-1)),p(r,{href:"http://linux.cn/"},{default:s(()=>[...t[25]||(t[25]=[e("Linux中國",-1)])]),_:1}),t[28]||(t[28]=e(" 榮譽推出",-1))])])}const _=o(f,[["render",m]]);export{T as __pageData,_ as default};
